1	import { duelistMoveset, movesetVersion, type DuelButton, type DuelMove, type DuelMoveset } from "@pirate-sea-race/content/moves";
2	import type { Facing } from "./boxes.js";
3	
4	/** Static duel data the step reads; it never changes during a duel. */
5	export interface DuelConfig {
6	  readonly moveset: DuelMoveset;
7	}
8	
9	export const defaultDuelConfig: DuelConfig = { moveset: duelistMoveset };
10	
11	/**
12	 * What a fighter is doing. `idle`, `walk` and `crouch` are free: the fighter can start anything on the next frame.
13	 * `jump` lasts until landing. The others are timed by `timer`.
14	 */
15	export type FighterAction =
16	  | "idle"
17	  | "walk"
18	  | "crouch"
19	  | "jump"
20	  | "dash"
21	  | "backdash"
22	  | "attack"
23	  | "hitstun"
24	  | "blockstun"
25	  | "stagger"
26	  | "thrown"
27	  | "throw-break"
28	  | "knockdown";
29	
30	export type Stance = "standing" | "crouching" | "airborne";
31	
32	/** Frames each button press stays usable (0 = no press waiting). */
33	export type InputBuffer = Readonly<Record<DuelButton, number>>;
34	
35	/**
36	 * One fighter. Every number is an integer: positions in sub-pixels (x from the left wall, y up from the floor, the
37	 * origin in the middle of the feet), velocities in sub-pixels per frame, durations in frames.
38	 */
39	export interface FighterState {
40	  readonly x: number;
41	  readonly y: number;
42	  readonly vx: number;
43	  readonly vy: number;
44	  readonly facing: Facing;
45	  readonly health: number;
46	  readonly stamina: number;
47	  /** Frames since stamina was last spent or a block was taken. */
48	  readonly staminaIdle: number;
49	  readonly action: FighterAction;
50	  /** Frames spent in the current action, counting the frame that started it. For an attack, the move's frame. */
51	  readonly actionFrame: number;
52	  /** Frames of the current timed action still to come; the fighter is free on the frame after it reaches 0. */
53	  readonly timer: number;
54	  /** The move being performed, while `action` is `attack`. */
55	  readonly moveId: string | null;
56	  /** The current move already connected (hit, block or grab); a move connects once. */
57	  readonly moveHit: boolean;
58	  /** Crouching stance while grounded (crouch, a crouching move, a crouching block or hit). */
59	  readonly crouching: boolean;
60	  /** Damaging hits taken in the current combo. */
61	  readonly combo: number;
62	  /** Last frame's input bits, to find newly pressed buttons. */
63	  readonly held: number;
64	  readonly buffer: InputBuffer;
65	}
66	
67	export type DuelPhase = "round" | "overtime" | "over";
68	
69	export type PlayerIndex = 0 | 1;
70	
71	export type DuelEventKind = "hit" | "block" | "guard-break" | "grab" | "throw" | "throw-escape" | "throw-clash";
72	
73	/** Something that happened on the frame that produced the state; `attacker` is the fighter whose move it was. */
74	export interface DuelEvent {
75	  readonly kind: DuelEventKind;
76	  readonly attacker: PlayerIndex;
77	  readonly moveId: string;
78	  /** Health taken by this event, after combo scaling. */
79	  readonly damage: number;
80	}
81	
82	export interface DuelResult {
83	  /** `null` is a draw. */
84	  readonly winner: PlayerIndex | null;
85	  readonly reason: "ko" | "double-ko" | "timeout" | "overtime";
86	  readonly frame: number;
87	}
88	
89	/** The complete duel: plain, serializable data, all of it covered by `hashState`. */
90	export interface DuelState {
91	  /** `movesetVersion()` of the move data this duel runs on; stepping, restoring or replaying on other data is refused. */
92	  readonly movesetVersion: string;
93	  /** Frames stepped since the duel began (the round's clock is `roundFrames - frame`). */
94	  readonly frame: number;
95	  readonly phase: DuelPhase;
96	  /** A seeded generator state (see `random.ts`), carried in every snapshot; no current rule draws from it. */
97	  readonly rng: number;
98	  readonly fighters: readonly [FighterState, FighterState];
99	  /** What happened on the last frame. */
100	  readonly events: readonly DuelEvent[];
101	  readonly result: DuelResult | null;
102	}
103	
104	export interface DuelStartOptions {
105	  readonly seed?: number;
106	  /** Both fighters' starting x; by default `startGap` apart about the arena's centre. */
107	  readonly x?: readonly [number, number];
108	}
109	
110	const EMPTY_BUFFER: InputBuffer = { light: 0, heavy: 0, special1: 0, special2: 0, dash: 0 };
111	
112	/** Both fighters grounded, facing each other, with full health and stamina (§6). */
113	export function createDuelState(config: DuelConfig, options: DuelStartOptions = {}): DuelState {
114	  const { arena, rules, fighter } = config.moveset;
115	  const seed = options.seed ?? 0;
116	  if (!Number.isInteger(seed)) throw new RangeError(`seed must be an integer, got ${seed}`);
117	  const centre = arena.width / 2;
118	  const [x0, x1] = options.x ?? [centre - arena.startGap / 2, centre + arena.startGap / 2];
119	  for (const x of [x0, x1]) {
120	    if (!Number.isSafeInteger(x) || x < fighter.pushbox.halfWidth || x > arena.width - fighter.pushbox.halfWidth) {
121	      throw new RangeError(`start position ${x} is not an integer inside the walls`);
122	    }
123	  }
124	  const create = (x: number, facing: Facing): FighterState => ({
125	    x,
126	    y: 0,
127	    vx: 0,
128	    vy: 0,
129	    facing,
130	    health: rules.maxHealth,
131	    stamina: rules.maxStamina,
132	    staminaIdle: 0,
133	    action: "idle",
134	    actionFrame: 0,
135	    timer: 0,
136	    moveId: null,
137	    moveHit: false,
138	    crouching: false,
139	    combo: 0,
140	    held: 0,
141	    buffer: EMPTY_BUFFER,
142	  });
143	  const facing0: Facing = x1 >= x0 ? 1 : -1;
144	  return {
145	    movesetVersion: movesetVersion(config.moveset),
146	    frame: 0,
147	    phase: "round",
148	    rng: seed >>> 0,
149	    fighters: [create(x0, facing0), create(x1, facing0 === 1 ? -1 : 1)],
150	    events: [],
151	    result: null,
152	  };
153	}
154	
155	const TIMED: ReadonlySet<FighterAction> = new Set(["dash", "backdash", "attack", "hitstun", "blockstun", "stagger", "throw-break", "knockdown"]);
156	
157	/** Whether the fighter can start something on the next frame: free, or at the end of a timed action on the ground. */
158	export function canAct(fighter: FighterState): boolean {
159	  if (fighter.action === "idle" || fighter.action === "walk" || fighter.action === "crouch") return true;
160	  return TIMED.has(fighter.action) && fighter.timer === 0 && fighter.y === 0 && fighter.vy === 0;
161	}
162	
163	export function findMove(moveset: DuelMoveset, id: string): DuelMove {
164	  const move = moveset.moves.find((candidate) => candidate.timing.id === id);
165	  if (move === undefined) throw new Error(`unknown move "${id}"`);
166	  return move;
167	}
168	
169	export function moveDuration(move: DuelMove): number {
170	  return move.timing.startup + move.timing.active + move.timing.recovery;
171	}
