307	    const start = createDuelState(config, { x: [8000, 9200] });
308	    expect(normal(mirrorState(start))).toEqual(normal(createDuelState(config, { x: [width - 9200, width - 8000] })));
309	    const a = expectMirrored(start, exchange);
310	    // The exchange really contains simultaneous and opposing events, starting with the jab trade: both players' jabs,
311	    // pressed on frame 21, hit each other on frame 28.
312	    expect(sortedEvents(a[28]!.events).map(({ kind, attacker, moveId }) => `${kind} ${attacker} ${moveId}`)).toEqual(["hit 0 jab", "hit 1 jab"]);
313	    const kinds = new Set(a.flatMap((state) => state.events.map((event) => event.kind)));
314	    expect([...kinds].sort()).toEqual(expect.arrayContaining(["block", "grab", "hit", "throw", "throw-clash", "throw-escape"]));
315	  });
316	
317	  it("separates an exact tie (equal x and equal facing) the same way on both sides", () => {
318	    // Player one dashes into player two, who staggers facing the same way; both end the movement on x = 5064.
319	    const start = createDuelState(config, { x: [5000, 5064] });
320	    const tie: DuelState = {
321	      ...start,
322	      fighters: [
323	        { ...start.fighters[0], action: "dash", actionFrame: 1, timer: 10, vx: 64, facing: 1 },
324	        { ...start.fighters[1], action: "stagger", actionFrame: 1, timer: 10, facing: 1 },
325	      ],
326	    };
327	    const a = expectMirrored(tie, hold(20));
328	    // The dasher came from the left, so it stays on the left: each moves half the overlap.
329	    expect(a[1]!.fighters.map((fighter) => fighter.x)).toEqual([5064 - 256, 5064 + 256]);
330	  });
331	});
